<?php
declare(strict_types=1);
namespace App\Tests\Unit\Assistant;
use App\Application\Assistant\DTO\Request\CreateAssistantMessageRequestDto;use App\Application\Assistant\Mapper\AssistantResponseMapper;use App\Application\Assistant\Port\AssistantProviderInterface;use App\Application\Assistant\Service\SendAssistantMessageService;use App\Domain\Assistant\Entity\AssistantConversation;use App\Domain\Assistant\Entity\AssistantMessage;use App\Domain\Assistant\Repository\AssistantConversationRepositoryInterface;use App\Domain\Assistant\Repository\SyllabusEvidenceRetrieverInterface;use App\Domain\Assistant\ValueObject\AssistantGeneratedAnswer;use App\Domain\Assistant\ValueObject\SyllabusEvidence;use PHPUnit\Framework\TestCase;
final class SendAssistantMessageServiceTest extends TestCase { public function testStoresAuditedAnswerWithRetrievedEvidence():void{$repository=new class implements AssistantConversationRepositoryInterface { public array $messages=[];public function saveConversation(AssistantConversation $c):void{}public function findConversationForUser(string $id,string $user):?AssistantConversation{return $id==='conversation'&&$user==='user'?new AssistantConversation('conversation','user','syllabus','Titulo',new \DateTimeImmutable(),new \DateTimeImmutable()):null;}public function listConversationsForUser(string $u):array{return [];}public function saveMessage(AssistantMessage $m):void{$this->messages[]=$m;}public function listMessagesForConversation(string $id):array{return $this->messages;}};$retriever=new class implements SyllabusEvidenceRetrieverInterface { public function retrieve(string $s,string $q,int $l=3):array{return [new SyllabusEvidence(4,'Conteúdo do edital')];}public function listAvailable():array{return[];}};$provider=new class implements AssistantProviderInterface { public function answer(string $q,array $e):AssistantGeneratedAnswer{return new AssistantGeneratedAnswer('Resposta evidenciada','test','v1',$e);}};$response=(new SendAssistantMessageService($repository,$retriever,$provider,new AssistantResponseMapper()))->sendForUser('user',new CreateAssistantMessageRequestDto('conversation','Qual o conteúdo?'));self::assertSame('ASSISTANT',$response->role);self::assertSame(4,$response->evidence[0]['pageNumber']);self::assertCount(2,$repository->messages);} public function testDoesNotExposeAnotherUsersConversation():void{$repository=new class implements AssistantConversationRepositoryInterface {public function saveConversation(AssistantConversation $c):void{}public function findConversationForUser(string $i,string $u):?AssistantConversation{return null;}public function listConversationsForUser(string $u):array{return[];}public function saveMessage(AssistantMessage $m):void{}public function listMessagesForConversation(string $i):array{return[];}};$retriever=new class implements SyllabusEvidenceRetrieverInterface {public function retrieve(string $s,string $q,int $l=3):array{return[];}public function listAvailable():array{return[];}};$provider=new class implements AssistantProviderInterface {public function answer(string $q,array $e):AssistantGeneratedAnswer{throw new \LogicException();}};$this->expectException(\DomainException::class);(new SendAssistantMessageService($repository,$retriever,$provider,new AssistantResponseMapper()))->sendForUser('user',new CreateAssistantMessageRequestDto('other','Pergunta'));} }
